WITH cleaned AS (SELECT id, customer_id, balance, status, INITCAP(TRIM(status)) status_title FROM accounts WHERE balance > 59000) SELECT *, MIN(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_min_balance, MAX(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_max_balance, SUM(balance) OVER (PARTITION BY customer_id ORDER BY balance, id ROWS BETWEEN 2 PRECEDING AND CURRENT ROW) last3_sum_balance FROM cleaned WHERE customer_id IS NOT NULL;
